#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    vector<string> grid(N);
    for (int i = 0; i < N; i++) {
        cin >> grid[i];
    }

    vector<int> q;
    q.reserve(N * M);

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            if (grid[i][j] == 'o') {
                q.push_back(i * M + j);
            }
        }
    }

    size_t head = 0;

    while (head < q.size()) {
        int id = q[head++];
        int i = id / M;
        int j = id % M;

        // Water falling vertically.
        if (i + 1 < N && grid[i + 1][j] == '.') {
            grid[i + 1][j] = 'o';
            q.push_back((i + 1) * M + j);
        }

        // Water running horizontally over a shelf.
        if (i + 1 < N && grid[i + 1][j] == '#') {
            if (j > 0 && grid[i][j - 1] == '.') {
                grid[i][j - 1] = 'o';
                q.push_back(i * M + (j - 1));
            }

            if (j + 1 < M && grid[i][j + 1] == '.') {
                grid[i][j + 1] = 'o';
                q.push_back(i * M + (j + 1));
            }
        }
    }

    for (int i = 0; i < N; i++) {
        cout << grid[i] << '\n';
    }

    return 0;
}
